function reloadPage(world) {
  const hash = world.window ? world.window.location.hash : '';
  // Sync current localStorage to shared storage before dispose
  if (world.window && world.window.localStorage) {
    const ls = world.window.localStorage;
    for (let i = 0; i < ls.length; i++) {
      const k = ls.key(i);
      sharedLocalStorage[k] = ls.getItem(k);
    }
  }
  world.disposeApp();
  world.loadApp();
  // Restore hash after reload
  if (hash) {
    world.window.location.hash = hash;
    world.window.dispatchEvent(new world.window.Event('hashchange'));
  }
}

